import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = () => {
  const [messages, setMessages] = useState([]);
  const [isLive, setIsLive] = useState(false);
  const [caption, setCaption] = useState("Click Mic to Initialize AI");
  const [inputValue, setInputValue] = useState('');
  const [step, setStep] = useState('idle'); 
  const [selectedLang, setSelectedLang] = useState('en-IN');
  const scrollRef = useRef(null);

  // --- FULL SERVICE DATA WITH HIGH-QUALITY IMAGES ---
  const services = [
    { name: "Booking", img: "https://images.unsplash.com/photo-1436491865332-7a61a109c05d?auto=format&fit=crop&w=150&q=80", desc: "Search & Book" },
    { name: "Status", img: "https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=150&q=80", desc: "Flight Tracking" },
    { name: "Check-in", img: "https://images.unsplash.com/photo-1483450388369-9ed95738483c?auto=format&fit=crop&w=150&q=80", desc: "Get Boarding Pass" },
    { name: "Baggage", img: "https://images.unsplash.com/photo-1581553674786-63febb0e5bb0?auto=format&fit=crop&w=150&q=80", desc: "Weight & Status" },
    { name: "Refund", img: "https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=150&q=80", desc: "Claim Processing" },
    { name: "Lounge", img: "https://images.unsplash.com/photo-1569154941061-e231b4725ef1?auto=format&fit=crop&w=150&q=80", desc: "Luxury Access" },
    { name: "Assistance", img: "https://images.unsplash.com/photo-1521791136064-7986c2959513?auto=format&fit=crop&w=150&q=80", desc: "Special Care" },
    { name: "Loyalty", img: "https://images.unsplash.com/photo-1556740738-b6a63e27c4df?auto=format&fit=crop&w=150&q=80", desc: "Points & Rewards" },
    { name: "Agent", img: "https://images.unsplash.com/photo-1549923746-c502d488b3ea?auto=format&fit=crop&w=150&q=80", desc: "Talk to Human" },
    { name: "Info", img: "https://images.unsplash.com/photo-1454165205744-3b78555e5572?auto=format&fit=crop&w=150&q=80", desc: "Travel Policy" }
  ];

  const speak = (text, lang, callback) => {
    const msg = new SpeechSynthesisUtterance(text);
    msg.lang = lang;
    msg.onstart = () => setCaption(text);
    msg.onend = () => callback && callback();
    window.speechSynthesis.speak(msg);
  };

  // --- NATIVE ACCENT LANGUAGE LOOP ---
  const startLanguageSelection = (index = 0) => {
    const langs = [
      { t: "For English, Press 1", l: "en-GB" },
      { t: "తెలుగు కోసం, రెండు నొక్కండి", l: "te-IN" },
      { t: "हिंदी के लिए, तीन दबाएं", l: "hi-IN" },
      { t: "മലയാളത്തിനായി, നാല് അമർത്തുക", l: "ml-IN" },
      { t: "தமிழுக்கு, ஐந்தை அழுத்தவும்", l: "ta-IN" },
      { t: "ಕನ್ನಡಕ್ಕಾಗಿ, ಆರನ್ನು ಒತ್ತಿ", l: "kn-IN" },
      { t: "বাংলার জন্য, সাত টিপুন", l: "bn-IN" },
      { t: "मराठीसाठी, आठ दाबा", l: "mr-IN" },
      { t: "ગુજરાતી માટે, નવ દબાવો", l: "gu-IN" },
      { t: "ਪੰਜਾਬੀ ਲਈ, ਦਸ ਦਬਾਓ", l: "pa-IN" }
    ];

    if (step !== 'language' || index >= langs.length) return;

    speak(langs[index].t, langs[index].l, () => {
      // Re-triggers mic after every 3 languages to see if user answered
      if ((index + 1) % 3 === 0) startListening();
      setTimeout(() => startLanguageSelection(index + 1), 400);
    });
  };

  const startListening = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) return;
    const recognition = new SpeechRecognition();
    recognition.lang = selectedLang;
    recognition.start();
    recognition.onresult = (event) => handleInteraction(event.results[0][0].transcript);
    recognition.onerror = () => { if(isLive) startListening(); }; // Keep listening
  };

  const handleInteraction = (val) => {
    const input = val.toLowerCase();
    addMessage("You", val);
    window.speechSynthesis.cancel(); // STOPS dictating other languages immediately

    if (step === 'language') {
      if (input.includes("1") || input.includes("english")) {
        setSelectedLang('en-GB'); setStep('service');
        speak("English Selected. Please choose a service from the visual list.", "en-GB", () => startListening());
      } else if (input.includes("2") || input.includes("తెలుగు") || input.includes("telugu")) {
        setSelectedLang('te-IN'); setStep('service');
        speak("తెలుగు ఎంపిక చేయబడింది. దయచేసి సేవను ఎంచుకోండి.", "te-IN", () => startListening());
      } else { startListening(); } // If noise, keep listening
    } 

    else if (step === 'service') {
      if (input.includes("booking") || input.includes("1")) {
        setStep('booking_flow');
        speak("Where is your destination?", selectedLang, () => startListening());
      } else if (input.includes("baggage") || input.includes("4")) {
        setStep('baggage_flow');
        speak("Please provide your PNR for baggage status.", selectedLang, () => startListening());
      }
    }
    // ... Additional flows (Weather/Booking) follow same pattern
  };

  const addMessage = (sender, text) => {
    setMessages(prev => [...prev, { sender, text, time: new Date().toLocaleTimeString() }]);
  };

  return (
    <div style={{background: '#f8fafc', height: '100vh', display: 'flex', flexDirection: 'column', fontFamily: 'Inter, sans-serif'}}>

      {/* HEADER - LOCKED TO UI SPEC */}
      <div style={{background: 'white', padding: '12px 40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #e2e8f0'}}>
        <div style={{display: 'flex', alignItems: 'center', gap: '12px'}}>
           <div style={{background: '#2563eb', color: 'white', padding: '8px', borderRadius: '10px'}}>✈️</div>
           <b>FLIGHT BOOKING <span style={{fontSize: '9px', color: '#64748b', display: 'block'}}>VOICE ASSISTANT</span></b>
        </div>
        <div style={{display: 'flex', background: '#f1f5f9', padding: '4px', borderRadius: '25px'}}>
           <button style={{padding: '6px 20px', borderRadius: '20px', border: 'none', background: 'transparent'}}>Voice Call</button>
           <button style={{padding: '6px 20px', borderRadius: '20px', border: 'none', background: '#2563eb', color: 'white'}}>Voice Web</button>
        </div>
        <div style={{display: 'flex', alignItems: 'center', gap: '20px'}}>
           <span>🔔</span><span>❓</span>
           <div style={{width: '35px', height: '35px', borderRadius: '50%', background: '#cbd5e1', border: '2px solid white'}}></div>
        </div>
      </div>

      {/* MAIN 3-COLUMN LAYOUT */}
      <div style={{display: 'grid', gridTemplateColumns: '300px 1fr 300px', gap: '20px', padding: '20px', flex: 1, overflow: 'hidden'}}>

        {/* LEFT: VISUAL SERVICE LIST */}
        <div style={{background: 'white', borderRadius: '24px', padding: '20px', overflowY: 'auto', boxShadow: '0 4px 10px rgba(0,0,0,0.02)'}}>
          <h4 style={{fontSize: '15px', marginBottom: '15px'}}>Flight Services</h4>
          {services.map((s, i) => (
            <div key={i} style={{display: 'flex', alignItems: 'center', gap: '15px', padding: '12px', marginBottom: '10px', borderRadius: '16px', background: step === 'service' ? '#f0f7ff' : 'white', border: '1px solid #f1f5f9'}}>
               <img src={s.img} alt={s.name} style={{width: '45px', height: '45px', borderRadius: '10px', objectFit: 'cover'}} />
               <div>
                  <div style={{fontSize: '13px', fontWeight: 'bold'}}>{i+1}. {s.name}</div>
                  <div style={{fontSize: '10px', color: '#64748b'}}>{s.desc}</div>
               </div>
            </div>
          ))}
        </div>

        {/* MIDDLE: SPLIT LAYOUT */}
        <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px'}}>
           <div style={{background: 'white', borderRadius: '24px', padding: '30px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
              <p style={{fontSize: '12px', color: '#64748b', textAlign: 'center', minHeight: '40px'}}>{caption}</p>
              <div onClick={() => { setStep('language'); startLanguageSelection(); setIsLive(true); }} style={{width: '200px', height: '200px', borderRadius: '50%', background: 'radial-gradient(circle, #2563eb 0%, #1e3a8a 100%)', display: 'flex', justifyContent: 'center', alignItems: 'center', cursor: 'pointer'}} className={isLive ? 'pulse-mic' : ''}>
                 <span style={{fontSize: '60px'}}>🎙️</span>
              </div>
              <p style={{marginTop: '25px', color: '#2563eb', fontWeight: 'bold'}}>● {isLive ? 'AI LISTENING' : 'START ASSISTANT'}</p>
           </div>

           <div style={{background: 'white', borderRadius: '24px', padding: '20px', display: 'flex', flexDirection: 'column', overflow: 'hidden'}}>
              <b style={{fontSize: '13px', marginBottom: '15px'}}>Live Captions / Transcript</b>
              <div style={{flex: 1, overflowY: 'auto'}} ref={scrollRef}>
                {messages.map((m, i) => (
                  <div key={i} style={{marginBottom: '10px', background: m.sender === 'You' ? '#eff6ff' : '#f8fafc', padding: '12px', borderRadius: '15px'}}>
                    <div style={{fontSize: '9px', color: '#2563eb', fontWeight: 'bold'}}>{m.sender}</div>
                    <div style={{fontSize: '12px'}}>{m.text}</div>
                  </div>
                ))}
              </div>
           </div>
        </div>

        {/* RIGHT: WEATHER & QUICK HELP */}
        <div style={{background: 'white', borderRadius: '24px', padding: '20px'}}>
           <h4 style={{fontSize: '15px', marginBottom: '20px'}}>Live Destination Info</h4>
           <div style={{background: 'linear-gradient(to bottom right, #2563eb, #1e40af)', borderRadius: '20px', padding: '20px', color: 'white', marginBottom: '20px'}}>
              <img src="https://images.unsplash.com/photo-1504608524841-42fe6f032b4b?auto=format&fit=crop&w=200&q=80" style={{width: '100%', borderRadius: '10px', marginBottom: '10px'}} />
              <div style={{fontSize: '24px', fontWeight: 'bold'}}>28°C</div>
              <div style={{fontSize: '12px'}}>Hyderabad - Sunny</div>
           </div>
           {['Track Flight', 'Baggage Help', 'Terminal Map'].map(q => (
             <div key={q} style={{padding: '12px', border: '1px solid #f1f5f9', borderRadius: '12px', marginBottom: '10px', fontSize: '12px', display: 'flex', alignItems: 'center', gap: '10px'}}>
               <span style={{color: '#2563eb'}}>🔗</span> {q}
             </div>
           ))}
        </div>
      </div>

      {/* BOTTOM INPUT */}
      <div style={{background: 'white', padding: '15px 40px', borderTop: '1px solid #e2e8f0', display: 'flex', gap: '15px'}}>
        <input type="text" placeholder="Type your selection..." value={inputValue} onChange={(e) => setInputValue(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleInteraction(inputValue)} style={{flex: 1, padding: '12px 25px', borderRadius: '30px', border: '1px solid #e2e8f0', background: '#f8fafc'}} />
        <button onClick={() => handleInteraction(inputValue)} style={{background: '#2563eb', color: 'white', border: 'none', padding: '0 35px', borderRadius: '30px', cursor: 'pointer'}}>Send</button>
      </div>

      <style>{`
        .pulse-mic { animation: ripple 1.8s infinite; }
        @keyframes ripple {
          0% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0.4); }
          70% { box-shadow: 0 0 0 30px rgba(37, 99, 235, 0); }
          100% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0); }
        }
      `}</style>
    </div>
  );
};

export default VoiceWeb;
